using namespace std;

class CodeforcesC {
private:
    bool ONLINE_JUDGE;
    istream* in;
    ostream* out;
    vector<string> tokens;
    size_t tokenIndex;

    void init() {
        ONLINE_JUDGE = true;
        in = &cin;
        out = &cout;
    }

    string readString() {
        if (tokenIndex >= tokens.size()) {
            string line;
            if (!getline(*in, line)) {
                return "";
            }
            istringstream iss(line);
            tokens.clear();
            string token;
            while (iss >> token) {
                tokens.push_back(token);
            }
            tokenIndex = 0;
        }
        return tokens[tokenIndex++];
    }

    int readInt() {
        return stoi(readString());
    }

    long long readLong() {
        return stoll(readString());
    }

    double readDouble() {
        return stod(readString());
    }

    vector<int> readIntArray(int n) {
        vector<int> array(n);
        for (int i = 0; i < n; i++) {
            array[i] = readInt();
        }
        return array;
    }

    void solve() {
        int l = readInt();
        int r = readInt();

        int n = 9;
        vector<int> ten(n + 1);
        ten[0] = 1;
        for (int i = 1; i <= n; i++) {
            ten[i] = 10 * ten[i - 1];
        }

        long long answer = 0;

        vector<long long> luckyNumbers;

        for (int length = 1; length <= n; length++) {
            for (int cur = 0; cur < (1 << length); cur++) {
                int value = 0;
                for (int j = 0; j < length; j++) {
                    if ((1 << j) & cur) {
                        value += ten[j] * 7;
                    } else {
                        value += ten[j] * 4;
                    }
                }
                luckyNumbers.push_back(value);
            }
        }

        luckyNumbers.push_back(4444444444LL);

        long long lastNumber = l;

        for (long long luckyNumber : luckyNumbers) {
            if (luckyNumber > r) {
                answer += (r - lastNumber + 1) * luckyNumber;
                break;
            }
            if (luckyNumber >= l) {
                answer += (luckyNumber - lastNumber + 1) * luckyNumber;
                lastNumber = luckyNumber + 1;
            }
        }

        *out << answer << endl;
    }

public:
    CodeforcesC() : ONLINE_JUDGE(false), in(nullptr), out(nullptr), tokenIndex(0) {}

    void run() {
        init();
        solve();
    }
};

int main() {
    CodeforcesC().run();
    return 0;
}

